import { z } from 'zod'

import { canonicalize, jsonObjectSchema } from './json.ts'
import { skillAssetSchema, taskTemplateSchema, toolAssetSchema } from './method.ts'
import { refSchema } from './refs.ts'
import { closedObject, parseProtocolValue } from './schema.ts'
import { taskExampleSchema } from './task.ts'

/** Model-authored asset content; immutable refs and digests are generated by the host. */
export const templateDraftSchema = taskTemplateSchema.omit({ guidance: true, example: true }).extend({
  guidance: z.string(),
  example: taskExampleSchema,
})
export type TemplateDraft = z.infer<typeof templateDraftSchema>

export const skillDraftSchema = skillAssetSchema.omit({ bundle: true }).extend({
  files: z.record(z.string(), z.string()),
})
export type SkillDraft = z.infer<typeof skillDraftSchema>

export const mcpServerDraftSchema = toolAssetSchema.omit({ server: true }).extend({
  server: toolAssetSchema.shape.server.omit({
    bundle: true, manifest: true, sourceFiles: true, config: true,
  }).extend({
    files: z.record(z.string(), z.string()),
    manifest: jsonObjectSchema,
    config: jsonObjectSchema,
  }),
})
export type McpServerDraft = z.infer<typeof mcpServerDraftSchema>

/** The closed MethodPatch operation set from framework §17.2. */
export const methodPatchSchema = closedObject({
  v: z.literal(1),
  base: refSchema,
  hypothesis: z.string(),
  changes: z.array(z.discriminatedUnion('op', [
    closedObject({ op: z.literal('put-template'), template: templateDraftSchema }),
    closedObject({ op: z.literal('remove-template'), id: z.string() }),
    closedObject({ op: z.literal('put-skill'), skill: skillDraftSchema }),
    closedObject({ op: z.literal('remove-skill'), id: z.string() }),
    closedObject({ op: z.literal('put-mcp-server'), server: mcpServerDraftSchema }),
    closedObject({ op: z.literal('remove-mcp-server'), id: z.string() }),
    closedObject({ op: z.literal('set-entry'), templateId: z.string().nullable() }),
  ])).max(64),
  predictedRisks: z.array(z.string()),
  transferPlan: z.string(),
})
export type MethodPatch = z.infer<typeof methodPatchSchema>

/** Compact model-facing shape, derived from the same schema used at submission. */
export const methodPatchParameterShape = describeShape(z.toJSONSchema(methodPatchSchema))

function describeShape(schema: z.core.JSONSchema.JSONSchema | boolean | undefined): string {
  if (schema === undefined || typeof schema === 'boolean' || schema.$ref !== undefined) return 'json'
  if (schema.const !== undefined) return JSON.stringify(schema.const)
  if (schema.enum !== undefined) return schema.enum.map(value => JSON.stringify(value)).join('|')
  const variants = schema.oneOf ?? schema.anyOf
  if (variants !== undefined) return variants.map(describeShape).join(' | ')
  if (schema.type === 'array') {
    const item = Array.isArray(schema.items) ? schema.items.map(describeShape).join(',') : describeShape(schema.items)
    return `(${item})[]`
  }
  if (schema.type === 'object') {
    if (schema.properties === undefined) return `{[key:string]:${describeShape(schema.additionalProperties)}}`
    return `{${Object.entries(schema.properties).map(([key, value]) =>
      `${key}${schema.required?.includes(key) === true ? '' : '?'}:${describeShape(value)}`).join(',')}}`
  }
  return schema.type ?? 'json'
}

/** Parse at the model boundary, with the fixed canonical 256 KiB patch limit. */
export function parseMethodPatch(value: unknown): MethodPatch {
  const patch = parseProtocolValue(methodPatchSchema, value)
  if (new TextEncoder().encode(canonicalize(patch)).byteLength > 256 * 1024) {
    throw new Error('MethodPatch exceeds the 256 KiB limit')
  }
  return patch
}
